import json

from PIL import Image
import imagehash
import os

HASH_SIZE = 32


def compute_phash(image_path):
    image = Image.open(image_path)
    phash = str(imagehash.phash(image, hash_size=HASH_SIZE))  # Convert pHash to a string for storage
    return phash


def compute_phash_180(image_path):
    image = Image.open(image_path)
    rotated_image = image.rotate(180)
    phash = str(imagehash.phash(rotated_image, hash_size=HASH_SIZE))  # Convert pHash to a string for storage
    return phash


phash_dict = {}
phash_dict_180 = {}

image_root = "Database/ImageDB/Large"

count=0
for filename in os.listdir(image_root):
    name, extension = os.path.splitext(filename)
    phash_dict[name] = compute_phash(os.path.join(image_root, filename))
    phash_dict_180[name] = compute_phash_180(os.path.join(image_root, filename))
    count = count + 1
    print("Finish: ", count)

print(phash_dict, phash_dict_180)

